let nodes; try { nodes = global.get('mys_nodes', 'file') || {}; } catch (e) { nodes = global.get('mys_nodes') || {}; }
let now = Date.now();
let result = [];

for (const id in nodes) {
    let n = nodes[id];
    let age = (now - n.lastSeen) / 1000;
    let hb = n.lastHeartbeat ? (now - n.lastHeartbeat) / 1000 : 999999;
    let ack = n.lastAck ? (now - n.lastAck) / 1000 : 999999;
    let expInt = (n.cycleMs ? n.cycleMs : 60000) / 1000;
    let offThr = Math.min(21600, Math.max(300, 3 * expInt));

    let status = "ONLINE";
    if (age > offThr) {
        status = "OFFLINE";
    } else if (hb > 900) {
        status = "SEM HEARTBEAT";
    } else if (ack > 1800) {
        status = "SEM ACK";
    }
    n.status = status;

    let lastSeenStr = Math.round(age) + "s atrás";
    let heartbeatStr = n.lastHeartbeat ? Math.round(hb) + "s atrás" : "-";
    let ackStr = n.lastAck ? Math.round(ack) + "s atrás" : "-";

    result.push({
        nodeId: id,
        status: status,
        lastSeen: lastSeenStr,
        heartbeat: heartbeatStr,
        ack: ackStr
    });
}

msg.payload = result;
return msg;

var prefix = global.get('mqtt_topic_prefix') || 'm360/DF/0000';
var m = msg.payload;
if (typeof m === 'string') {
    try { m = JSON.parse(m); } catch(e) {}
}
if (m && typeof m === 'object' && m.nodeId !== undefined) {
    var nodeId   = m.nodeId;
    var sensorId = m.sensorId !== undefined ? m.sensorId : 0;
    var command  = m.command !== undefined ? m.command : 1;
    var ack      = m.ack !== undefined ? m.ack : 0;
    var type     = m.type !== undefined ? m.type : 2;
    var payload  = m.payload !== undefined ? String(m.payload) : '';
    msg.topic = prefix + '/in/' + nodeId + '/' + sensorId + '/' + command + '/' + ack + '/' + type;
    msg.payload = payload;
} else {
    msg.topic = prefix + '/in';
}
return msg;

var m = msg.payload;
var nodeId = m.nodeId || 1;
var action = m.action || "REPRESENT";

var payloadObj = {};
if (action === "REPRESENT") {
    payloadObj = {
        nodeId: Number(nodeId),
        sensorId: 0,
        command: 1,
        type: 48,
        payload: "REPRESENT"
    };
} else if (action === "FORCE_UPDATE") {
    payloadObj = {
        nodeId: Number(nodeId),
        sensorId: 0,
        command: 1,
        type: 48,
        payload: "FORCE_UPDATE"
    };
} else if (action === "DEBUG") {
    payloadObj = {
        nodeId: Number(nodeId),
        sensorId: 0,
        command: 1,
        type: 48,
        payload: "DEBUG_NET"
    };
}
msg.payload = payloadObj;
return msg;

var prefix = global.get('mqtt_topic_prefix') || 'm360/DF/0000';
var m = msg.payload;
if (typeof m === 'string') {
    try { m = JSON.parse(m); } catch(e) {}
}
if (m && typeof m === 'object' && m.nodeId !== undefined) {
    var nodeId   = m.nodeId;
    var sensorId = m.sensorId !== undefined ? m.sensorId : 0;
    var command  = m.command !== undefined ? m.command : 1;
    var ack      = m.ack !== undefined ? m.ack : 0;
