flow.set('hist_solo_B', hist);
return msg;

var hist = flow.get('hist_solo_B') || [];
var msgs = hist.map(function(p) { return { topic: p.topic, payload: p.payload, ts: p.ts }; });
node.status({ fill: 'blue', shape: 'dot', text: 'replay B: ' + msgs.length + ' pontos' });
return [ msgs.length ? msgs : null ];

// Logger centralizado com amostragem/debounce de atualizacao para proteger o Dashboard
var logs = global.get('mqtt_logs') || [];
var dir = msg.mqtt_dir || 'IN';
var topic = msg.topic || 'N/A';
var payload = msg.payload;

var payloadStr = '';
if (typeof payload === 'object') {
    try { payloadStr = JSON.stringify(payload); } catch(e) { payloadStr = String(payload); }
} else {
    payloadStr = String(payload);
}

var entry = {
    timestamp: new Date().toISOString(),
    dir: dir,
    topic: topic,
    payload: payloadStr
};

logs.push(entry);
if (logs.length > 2000) {
    logs.shift();
}
global.set('mqtt_logs', logs);

// Throttle UI table updates (maximo 1 atualizacao a cada 800ms para evitar travamentos)
var lastUiUpdate = flow.get('mqtt_log_last_ui') || 0;
var now = Date.now();
if (now - lastUiUpdate < 800) {
    return null; // Acumula no log sem re-renderizar a tabela na UI
}
flow.set('mqtt_log_last_ui', now);

var recent = logs.slice(-100).reverse();
msg.payload = recent.map(function(item) {
    var d = new Date(item.timestamp);
    var pad = function(n) { return n < 10 ? '0' + n : n; };
    var timeStr = pad(d.getHours()) + ':' + pad(d.getMinutes()) + ':' + pad(d.getSeconds());
    var dateStr = pad(d.getDate()) + '/' + pad(d.getMonth() + 1) + '/' + d.getFullYear() + ' ' + timeStr;
    return {
        DataHora: dateStr,
        Direcao: item.dir,
        Topico: item.topic,
        Payload: item.payload
    };
});
return msg;

global.set('mqtt_logs', []);
msg.payload = [];
return msg;

var logs = global.get('mqtt_logs') || [];
var lines = [];
lines.push('"Timestamp","Direction","Topic","Payload"');

for (var i = 0; i < logs.length; i++) {
    var item = logs[i];
    var ts = item.timestamp || '';
    var dir = item.dir || '';
    var topic = (item.topic || '').replace(/"/g, '""');
    var payload = (item.payload || '').replace(/"/g, '""');
    lines.push('"' + ts + '","' + dir + '","' + topic + '","' + payload + '"');
}

var csvStr = lines.join('\n');
msg.headers = {
    'Content-Type': 'text/csv; charset=utf-8',
    'Content-Disposition': 'attachment; filename="mqtt_log_m360_' + Date.now() + '.csv"'
};
msg.payload = csvStr;
return msg;
